const dictionary = new Map(entries);
const replacements = [...dictionary].sort((a,b)=>b[0].length-a[0].length).map(([english,translation])=>{
  const escaped=english.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
  return [new RegExp(`(?<![A-Za-z])${escaped}(?![A-Za-z])`,'g'),translation];
});
const cache=new Map();

export function arabic(text) {
  if (!/[A-Za-z]/.test(text)) return text;
  if(cache.has(text))return cache.get(text);
  const trimmed=text.trim();
  if (dictionary.has(trimmed)) return text.replace(trimmed,dictionary.get(trimmed));
  let output=text;
  output=output.replace(/All sequences use (\d+) days and the same starting water and irrigation budget\./g,'تستخدم جميع التسلسلات $1 يوماً ومياه البداية وميزانية الري نفسيهما.');
  output=output.replace(/A complete (\d+) requires (\d+) daily rows; received (\d+)\. Gaps are not filled silently\./g,'تتطلب سنة $1 الكاملة $2 صفاً يومياً؛ تم استلام $3. لا تُملأ الفجوات بصمت.');
  output=output.replace(/(\d+) days cross your heat threshold/g,'تتجاوز $1 يوماً عتبة الحرارة المحددة');
  output=output.replace(/Version ([\d.]+)\. Export includes raw daily weather, coordinates, year, all crop calendars and coefficients, assumptions, daily outputs and source lineage\. Exports may contain private farm information\. Current drafts are saved only in this browser; no account or shared project database is implemented\./g,'الإصدار $1. يتضمن التصدير الطقس اليومي الخام والإحداثيات والسنة والتقاويم والمعاملات والافتراضات والنتائج ومصادر البيانات. قد تحتوي الملفات على معلومات حقل خاصة. تُحفظ المسودات في هذا المتصفح فقط؛ لا توجد حسابات أو قاعدة مشروعات مشتركة.');
  for (const [expression,translation] of replacements) output=output.replace(expression,translation);
  output=output.replace(/(\d+) of 4 setup steps complete · this is workflow progress, not scientific confidence\./g,'اكتملت $1 من ٤ خطوات إعداد · هذا تقدّم في العمل وليس مقياساً للثقة العلمية.');
  output=output.replace(/(\d+) of 4 workspace setup steps complete/g,'اكتملت $1 من ٤ خطوات الإعداد');
  output=output.replace(/(\d+) days cross your heat threshold/g,'تتجاوز $1 يوماً عتبة الحرارة المحددة');
  output=output.replace(/Daily maximum ≥/g,'الحرارة العظمى اليومية ≥').replace(/°C/g,'°م');
  output=output.replace(/available water/g,'مياه متاحة').replace(/FIELD NOTES \/ /g,'بيانات الحقل / ');
  output=output.replace(/All sequences use (\d+) days and the same starting water and irrigation budget\./g,'تستخدم جميع التسلسلات $1 يوماً ومياه البداية وميزانية الري نفسيهما.');
  output=output.replace(/must be between/g,'يجب أن تكون بين').replace(/ and /g,' و ');
  output=output.replace(/A complete (\d+) requires (\d+) daily rows; received (\d+)\. Gaps are not filled silently\./g,'تتطلب سنة $1 الكاملة $2 صفاً يومياً؛ تم استلام $3. لا تُملأ الفجوات بصمت.');
  if(cache.size>2000)cache.clear();cache.set(text,output);
  return output;
}

/** Translate original DOM copy, preserving machine-readable code and user-entered values. */
const originals=new WeakMap();
export function localize(root,language) {
  const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);
  const nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);
  for(const node of nodes){
    if(node.parentElement?.closest('script,style,code,pre,.code,[data-user-content]'))continue;
    if(!originals.has(node))originals.set(node,node.nodeValue);
    node.nodeValue=language==='ar'?arabic(originals.get(node)):originals.get(node);
  }
  for(const element of root.querySelectorAll('[aria-label],img[alt]')){
    for(const name of ['aria-label','alt']){
      if(!element.hasAttribute(name))continue;
      const key=`data-original-${name}`;
      if(!element.hasAttribute(key))element.setAttribute(key,element.getAttribute(name));
      const original=element.getAttribute(key);
      element.setAttribute(name,language==='ar'?arabic(original):original);
    }
  }
}

